css:
:scope{--ink:var(--os-color-text);--ink-soft:#2D4F51;--teal:#0F5457;--sand:#F5EEE2;--card:var(--os-color-surface);--rose:var(--os-color-accent);--line-gold:var(--os-color-border);--serif:'Cormorant Garamond', Georgia, serif;--sans:'Jost', system-ui, sans-serif}
:scope{color:var(--ink);font-family:var(--sans);font-weight:300;font-size:18px;line-height:1.75}
@media (max-width:767px){:scope{font-size:17px}}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
[class~="os-ci"]{max-width:100%;display:block}
img{display:block}
a{color:var(--teal)}
a:hover{color:var(--rose)}
h2,h3{font-family:var(--serif);font-weight:300;margin:0;line-height:1.08;color:var(--teal)}
p{margin:0}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.eyebrow{font-size:14px;letter-spacing:.34em;text-transform:uppercase;color:var(--rose);font-weight:400}
section{padding:100px 0}
.center{text-align:center;display:flex;flex-direction:column;gap:14px;align-items:center}
.center h2{font-size:clamp(40px,5vw,64px)}
.bg-sand{background:radial-gradient(ellipse 55% 45% at 50% 0%,rgba(240,200,110,.18),rgba(240,200,110,0) 70%),var(--sand)}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:24px;margin-top:48px}
.card{background:var(--card);border:1px solid var(--line-gold);border-radius:200px 200px 20px 20px;padding:12px 12px 32px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:14px;box-shadow:0 24px 60px -40px rgba(160,116,37,.55)}
.card [class~="os-ci"]{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:200px 200px 12px 12px}
.card img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:200px 200px 12px 12px}
.card h3{font-size:30px;font-weight:500;margin-top:6px}
.card p{font-size:16px;line-height:1.7;padding:0 16px;color:var(--ink-soft)}
.card a{margin-top:auto;font-size:14px;letter-spacing:.14em;text-transform:uppercase;padding:12px 4px;color:var(--rose)}
@media (max-width:767px){section{padding:72px 0}}
